use std::{alloc::{GlobalAlloc, Layout, System}, sync::atomic::{AtomicUsize, Ordering}, hint::black_box};
struct Counted;
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
unsafe impl GlobalAlloc for Counted {
    unsafe fn alloc(&self, l: Layout) -> *mut u8 { ALLOCS.fetch_add(1, Ordering::Relaxed); unsafe { System.alloc(l) } }
    unsafe fn dealloc(&self,p:*mut u8,l:Layout) { unsafe { System.dealloc(p,l) } }
    unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8 { ALLOCS.fetch_add(1,Ordering::Relaxed); unsafe { System.realloc(p,l,n) } }
}
#[global_allocator] static ALLOCATOR: Counted = Counted;
#[derive(Clone, Copy, Debug, PartialEq)]
struct Allocation { object: *mut (), size: usize, identity: usize }
unsafe extern "C" { fn clock_gettime_nsec_np(clock:u32)->u64; }
#[inline(never)] fn baseline(allocations:&[Allocation],marked:&[u8])->Vec<Allocation> {
    allocations.iter().enumerate().filter(|(i,_)| marked[*i]==0).map(|(_,a)| *a).collect()
}
#[inline(never)] fn candidate(allocations:&mut Vec<Allocation>,marked:&[u8])->Vec<Allocation> {
    let mut dead=std::mem::take(allocations);
    let mut marks=marked.iter(); dead.retain(|_| *marks.next().unwrap()==0); dead
}
fn main(){
    for n in [1024,65536,1048576] {
        let source:Vec<_>=(0..n).map(|i|Allocation{object:std::ptr::without_provenance_mut((i+1)*16),size:i%24,identity:i+1}).collect();
        for percent in [0,50,100] {
            let marks:Vec<u8>=(0..n).map(|i|u8::from(i%100>=percent)).collect();
            let expected:Vec<_>=source.iter().copied().zip(&marks).filter_map(|(v,&m)|(m==0).then_some(v)).collect();
            for sample in 0..8 {
                for lane in if sample%2==0 { ["baseline","candidate"] } else { ["candidate","baseline"] } {
                    let mut allocations=source.clone();
                    let before=ALLOCS.load(Ordering::Relaxed);
                    let start=unsafe{clock_gettime_nsec_np(16)};
                    let dead=if lane=="baseline" {baseline(black_box(&allocations),black_box(&marks))}else{candidate(black_box(&mut allocations),black_box(&marks))};
                    let elapsed=unsafe{clock_gettime_nsec_np(16)}-start;
                    let allocations_made=ALLOCS.load(Ordering::Relaxed)-before;
                    assert_eq!(dead,expected);
                    if lane=="candidate" { assert_eq!(allocations_made,0); }
                    println!("{n} {percent} {sample} {lane} {elapsed} {allocations_made} {}",(allocations.capacity()+dead.capacity())*size_of::<Allocation>());
                }
            }
        }
    }
}

